"""Bounded candidate-only perturbations of four previously reviewed pipelines."""
import copy
import json
import math
from pathlib import Path

ROOT=Path('/home/russell/wt/crypto-predictability-15-20261017')
BASE=ROOT/'children/crypto_trading'
OUT=Path('/home/russell/data/crypto_trading/research/pocket-tuning-20261018')
CUT=1777680000000
DAY=86400000
SPECS={}
for parent in [24,48,44,38]:
    for strength in [.25,.5,.75]:
        SPECS[len(SPECS)+1]=dict(parent=parent,strength=strength,name=f'p{parent}-strength-{int(strength*100):03d}',rationale='Test how far to move from market probability; smaller corrections may preserve calibration and larger ones may reveal under-correction.')
for parent in [24,48,44]:
    for threshold in [1000.,100000.]:
        SPECS[len(SPECS)+1]=dict(parent=parent,threshold=threshold,name=f'p{parent}-pruning-{int(threshold)}',rationale='Test stronger versus weaker ARD feature pruning; precision thresholds change retained predictors rather than adding features.')
for multiplier in [.5,2.]:
    SPECS[len(SPECS)+1]=dict(parent=48,vol_threshold=math.log(multiplier),name=f'p48-vol-boundary-{int(multiplier*100):03d}',rationale='Test sensitivity of the volatility-regime boundary to a fixed half/double scaling; do not estimate the boundary from validation.')
CONTROLS={24:2,48:5,44:8,38:11}
def change_strength(x,strength):
    count=0
    if isinstance(x,dict):
        if x.get('op')=='mul' and x['args'][0]=={'const':.5} and x['args'][1].get('op')=='min':
            x['args'][0]['const']=strength
            return 1
        for v in x.values():count+=change_strength(v,strength)
    elif isinstance(x,list):
        for v in x:count+=change_strength(v,strength)
    return count
def make(i,stage):
    spec=SPECS[i]
    src=next((BASE/'configs').glob(f"run-warmup20-{stage}-{spec['parent']:02d}-*.json"))
    doc=json.loads(src.read_text());n=doc['pipeline']
    if 'strength' in spec:
        assert change_strength(n['probability']['params']['fields']['prediction'],spec['strength'])==1
    if 'threshold' in spec:n['fit']['params']['estimator_params']['threshold_lambda']=spec['threshold']
    if 'vol_threshold' in spec:n['group']['params']['cases'][0]['when'][0]['value']=spec['vol_threshold']
    for view in ['predictions','markets','cells','leads','asset_leads','calibration']:
        n['write_'+view]['params']['path']=str(OUT/'results'/f'{stage}-{i:02d}-{view}-{{run}}.jsonl')
    doc.update(name=f"crypto-pocket-tuning-{stage}-{i:02d}-{spec['name']}",outputs={'run_root':str(OUT/'runs'/('warmup-retry-01' if stage=='warmup' and i==1 else stage))},
      notes=f"Parent method {spec['parent']}; "+spec['rationale']+" Identical source, features, train schedule and benchmarks to aligned study. Warmup-only tuning and stability selection; validation choices fixed before execution. Previously explored historical replication only.")
    path=BASE/'configs'/f"run-pocket-tuning-{stage}-{i:02d}-{spec['name']}.json"
    path.write_text(json.dumps(doc,indent=2)+'\n')
    return path
if __name__=='__main__':
    (OUT/'results').mkdir(exist_ok=True)
    for stage in ['warmup','validation']:
        for i in SPECS:make(i,stage)
    (OUT/'specifications.json').write_text(json.dumps(SPECS,indent=2)+'\n')
    print('40 pipeline JSONs built: 16 perturbations and 4 exact controls, each at both stages.')
